import json, sys

def snippet(s, n=160):
    s = str(s).replace('\n', ' ')
    return s[:n] + ('…' if len(s) > n else '')

def process(obj):
    t = obj.get('type')
    ts = obj.get('timestamp', '')
    if t in ('attachment',):
        return f"{ts} [attachment]"
    if t == 'queue-operation':
        return f"{ts} [queue:{obj.get('operation')}] {snippet(obj.get('content',''))}"
    if t == 'user' or t == 'assistant':
        msg = obj.get('message', {})
        role = msg.get('role', t)
        content = msg.get('content')
        parts = []
        if isinstance(content, str):
            parts.append(snippet(content))
        elif isinstance(content, list):
            for c in content:
                ctype = c.get('type')
                if ctype == 'text':
                    parts.append(f"TEXT: {snippet(c.get('text',''))}")
                elif ctype == 'tool_use':
                    parts.append(f"TOOL_USE[{c.get('name')}]: {snippet(c.get('input',''))}")
                elif ctype == 'tool_result':
                    cont = c.get('content')
                    parts.append(f"TOOL_RESULT: {snippet(cont)}")
                elif ctype == 'thinking':
                    parts.append(f"THINKING: {snippet(c.get('thinking',''),80)}")
        usage = msg.get('usage')
        u = f" usage={usage.get('output_tokens')}" if usage else ""
        return f"{ts} [{role}]{u} " + " | ".join(parts)
    if t == 'summary':
        return f"{ts} [summary] {snippet(obj.get('summary',''))}"
    return f"{ts} [{t}] {snippet(obj)}"

path = sys.argv[1]
with open(path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception as e:
            print("PARSE_ERROR", e)
            continue
        print(process(obj))

